#include <windows.h>
#include <iostream>
#include <uiautomation.h>
void print(HWND h){wchar_t name[256]{};GetClassNameW(h,name,256);RECT r{};GetWindowRect(h,&r);std::wcout<<L"hwnd="<<reinterpret_cast<UINT_PTR>(h)<<L" parent="<<reinterpret_cast<UINT_PTR>(GetParent(h))<<L" class="<<name<<L" rect="<<r.left<<L","<<r.top<<L","<<r.right<<L","<<r.bottom<<L" visible="<<IsWindowVisible(h)<<L" dpi="<<GetDpiForWindow(h)<<L"\n";}
int main(int argc,char **argv){if(argc==3&&std::string(argv[1])=="--close-test-pid"){DWORD pid=strtoul(argv[2],nullptr,10);EnumWindows([](HWND h,LPARAM target)->BOOL{DWORD pid=0;GetWindowThreadProcessId(h,&pid);wchar_t c[128]{};GetClassNameW(h,c,128);if(pid==static_cast<DWORD>(target)&&wcscmp(c,L"PulseTrace.Desktop")==0)PostMessageW(h,RegisterWindowMessageW(L"PulseTrace.Widget.Action.v1"),7,0);return TRUE;},pid);return 0;}
 SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);std::cout<<"Foreground ";print(GetForegroundWindow());std::cout<<"Foreground style="<<GetWindowLongPtrW(GetForegroundWindow(),GWL_STYLE)<<"\n";auto bar=FindWindowW(L"Shell_TrayWnd",nullptr);if(!bar)return 2;print(bar);EnumChildWindows(bar,[](HWND h,LPARAM)->BOOL{print(h);return TRUE;},0);EnumWindows([](HWND h,LPARAM)->BOOL{wchar_t c[128]{};GetClassNameW(h,c,128);if(wcscmp(c,L"Shell_SecondaryTrayWnd")==0){print(h);EnumChildWindows(h,[](HWND n,LPARAM)->BOOL{print(n);return TRUE;},0);}return TRUE;},0);
 CoInitializeEx(nullptr,COINIT_MULTITHREADED);IUIAutomation2 *uia=nullptr;auto hr=CoCreateInstance(CLSID_CUIAutomation8,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&uia));std::cout<<"UIA result="<<hr<<"\n";
 if(uia){uia->put_ConnectionTimeout(250);uia->put_TransactionTimeout(250);IUIAutomationElement *element=nullptr;IUIAutomationCondition *condition=nullptr;IUIAutomationElementArray *items=nullptr;
  if(SUCCEEDED(uia->ElementFromHandle(FindWindowExW(bar,nullptr,L"Windows.UI.Composition.DesktopWindowContentBridge",nullptr),&element))&&SUCCEEDED(uia->CreateTrueCondition(&condition))&&SUCCEEDED(element->FindAll(TreeScope_Descendants,condition,&items))){int count=0;items->get_Length(&count);for(int i=0;i<count&&i<256;i++){IUIAutomationElement *item=nullptr;if(SUCCEEDED(items->GetElement(i,&item))){CONTROLTYPEID type{};RECT r{};BOOL off=TRUE;item->get_CurrentControlType(&type);item->get_CurrentIsOffscreen(&off);item->get_CurrentBoundingRectangle(&r);if(!off&&type!=UIA_PaneControlTypeId&&type!=UIA_GroupControlTypeId&&type!=UIA_ToolBarControlTypeId)std::cout<<"UIA type="<<type<<" rect="<<r.left<<","<<r.top<<","<<r.right<<","<<r.bottom<<"\n";item->Release();}}}
  if(items)items->Release();if(condition)condition->Release();if(element)element->Release();uia->Release();}CoUninitialize();}
